insert into public.data_sources (id, name, description, source_type, last_updated, status, coverage, granularity, feeds, records_in, records_mapped) values
  ('job-portals', 'Job portal postings', 'Synthetic extract in the shape of job-portal vacancy listings. Stands in for portal data until a real feed is agreed.', 'demand', '2026-09-28', 'prototype_synthetic', '7 pilot districts in 3 states', 'District × job title × month', 'Job postings (Demand Index, demand volume)', 6645, 6642),
  ('employment-exchange', 'Employment exchange vacancies (NCS-style)', 'Synthetic extract shaped like National Career Service vacancy registrations with NCO codes. No connection to NCS exists yet.', 'demand', '2026-09-28', 'prototype_synthetic', '7 pilot districts in 3 states', 'District × NCO unit group × month', 'Employment registrations (Demand Index, demand volume)', 2215, 2214),
  ('industry-hiring', 'Industry hiring intent', 'Synthetic employer hiring-intent scores (0–100) by role and location.', 'demand', '2026-09-28', 'prototype_synthetic', '7 pilot districts in 3 states', 'District × role × month', 'Hiring signal (Demand Index)', 2215, 2214),
  ('industry-survey', 'Industry demand outlook survey', 'Synthetic sector-skill-council style outlook scores (0–100) by trade and district.', 'demand', '2026-09-28', 'prototype_synthetic', '7 pilot districts in 3 states', 'District × trade × month', 'Industry demand signal (Demand Index)', 2212, 2211),
  ('training-capacity', 'Training capacity and outcomes', 'Synthetic seat allocation, enrolment, completion and placement by trade and district. Stands in for scheme MIS data.', 'supply', '2026-09-28', 'prototype_synthetic', '7 pilot districts in 3 states', 'District × trade × training year', 'Supply Index, supply forecast', 369, 369),
  ('nco-nsqf', 'NCO-2015 / NSQF classification', 'Indicative mapping of pilot trades to NCO-2015 unit groups and NSQF levels, built by hand for the prototype. Needs validation against the official registers.', 'reference', '2026-09-28', 'prototype_reference', '14 pilot trades', 'Trade', 'Occupation normalisation', null, null),
  ('ncs', 'National Career Service (NCS)', 'Planned source for vacancy and jobseeker registrations. Not connected.', 'demand', null, 'planned', 'National', 'District × occupation × month', 'Would replace the synthetic employment-exchange extract', null, null),
  ('e-shram', 'e-Shram', 'Planned source for the registered unorganised workforce by occupation and district. Not connected.', 'supply', null, 'planned', 'National', 'District × occupation', 'Would add available workforce to the supply side', null, null),
  ('plfs', 'Periodic Labour Force Survey (PLFS)', 'Planned source for employment structure by occupation and region, to benchmark demand levels. Not connected.', 'demand', null, 'planned', 'National, state and region', 'State × occupation group × quarter or year', 'Would calibrate demand volumes', null, null),
  ('scheme-mis', 'Scheme MIS (Skill India Digital Hub and state systems)', 'Planned source for sanctioned seats, enrolment, certification and placement. Not connected.', 'supply', null, 'planned', 'National', 'Centre × trade × batch', 'Would replace the synthetic training-capacity extract', null, null);
